about_disclaimer_title: "Aviso legal",
about_disclaimer_purpose: "O ps5upload é fornecido apenas para fins de pesquisa, educação, interoperabilidade e desenvolvimento homebrew. Não é afiliado, endossado ou vinculado à Sony Interactive Entertainment Inc. “PlayStation” e “PS5” são marcas registradas da Sony Interactive Entertainment Inc., usadas aqui apenas para identificação.",
about_disclaimer_piracy: "Use apenas com hardware que você possui e com conteúdo que você possui legalmente. Não deve ser usado para copiar, distribuir ou executar software que você não tem o direito de usar.",
about_disclaimer_risk: "Este software é fornecido “como está”, sem garantia de qualquer tipo. Operar um console modificado pode danificá-lo permanentemente, destruir de forma irreversível saves e licenças e resultar no banimento da sua conta ou do console. Você o usa inteiramente por sua conta e risco e assume total responsabilidade pelas consequências. Faça backup de tudo que não pode perder antes de começar.",
