volumes_pkg_copies_here: "As cópias de pacotes ficam aqui",
volumes_store_pkg_copies: "Guardar cópias de pacotes aqui",
volumes_pkg_copies_hint: "O que esta opção faz: “Enviar e instalar” primeiro copia o arquivo .pkg para o PS5 e depois instala a partir dessa cópia. Isto define apenas em qual unidade essas cópias ficam. Não muda onde os jogos são instalados (o PS5 decide isso nas próprias configurações de armazenamento), e “Transmitir e instalar” não guarda cópia nenhuma. Se a unidade escolhida não estiver conectada, as cópias vão para o armazenamento interno.",
saves_auto_folder_label: "Pasta de backup",
captures: "Capturas e clipes",
captures_title: "Capturas",
"arcpkg.choose": "Escolher arquivo compactado…",
"arcpkg.help": "Para um .zip, .7z ou .rar que contém um ou mais arquivos .pkg, em qualquer pasta. Só os pacotes são descompactados, direto no PS5 (nada é extraído neste computador), e depois instalados um a um: o jogo base antes da atualização, depois o DLC. Um RAR em várias partes (.part1.rar, .part2.rar…) funciona: escolha a primeira parte e mantenha as outras ao lado. A senha é pedida quando um RAR precisa dela; ZIP e 7z protegidos por senha não são suportados.",
"arcpkg.keepsRunning": "Isso continua rodando se você abrir outra tela; também aparece em Tarefas.",
"arcpkg.notArchive": "Esse arquivo não é um .zip, .7z ou .rar.",
