fs_send_dial_hint: "Deixe vazio para discar o endereço do próprio console. Com ps5-tailscale, crie um encaminhamento local no console de origem (página de status: 127.0.0.1:19120 → o outro console:9120) e informe 127.0.0.1:19120 aqui. Quem pode enviar é decidido pelas chaves dos consoles e por um ticket de uso único, não pelo endereço.",
