install_hint_setup_exe: "O instalador foi aberto: siga-o, e ele atualiza o PS5Upload no lugar.",
install_path_fallback_hint: "Um último recurso para um pacote que já está no PS5, quando o PS5 o recusa do próprio armazenamento e também não consegue buscá-lo deste computador. Usado só para um jogo base que não está instalado, então não pode remover nada. Não comprovado: funcionou no firmware 11.20 e é recusado no 13.60. Se você tentar, informe se funcionou.",
