"minion_lan_hint": "Desligado: só o navegador do próprio PS5 consegue abri-lo. Ligado: um celular, tablet ou computador na mesma rede também pode abri-lo, ou seja, qualquer pessoa nessa rede. Ligue só em casa.",
"minion_open_here": "Abrir aqui",
"minion_remove_note": "Remover desliga o Minion e apaga o que ele guarda no PS5: seus favoritos e pastas recentes de Arquivos, o cache da biblioteca de jogos e o log do controle. Compartilhamentos de rede, cheats e backups permanecem; o app do PC também os usa.",
