"rp_keep_hint": "Outras telas mantêm a transmissão; este é o tempo de espera quando nenhuma janela a exibe (fechada ou recarregada) antes de encerrar.",
"rp_game_mode_mac": "Enquanto você joga, o computador e a tela ficam ativos. A tela cheia também liga o Modo de Jogo (macOS 14 e posteriores).",
"rp_game_mode_ios": "O Modo de Jogo liga enquanto o app ocupa a tela (iOS e iPadOS 18 e posteriores).",
