"rp_controls_hint": "Um controle também funciona: conecte-o ou pareie com este dispositivo. Shift + arrastar na imagem é um dedo no touchpad.",
"rp_settings": "Configurações",
"rp_running_elsewhere": "Jogar está em uso em {name}",
"rp_show_here": "Mostrar aqui",
"rp_running_elsewhere_body": "Foi iniciado em outra janela ou antes de recarregar esta página, e continua ativo.",
"rpg_user_title": "Entre com um usuário no PS5",
"rpg_user_body": "No console, escolha o usuário com que você vai jogar. Ninguém precisa ficar na frente da tela, mas o usuário precisa estar conectado. Use um usuário sem senha de acesso: a senha impede o login automático quando o console liga.",
"rpg_account_title": "Dê um ID de conta a esse usuário",
"rpg_account_body": "A Reprodução Remota pareia com um ID de conta. Um usuário vinculado à PlayStation Network já tem um; um usuário offline precisa de um definido em Usuários, acima (qualquer ID serve; anote-o, os salvamentos feitos depois ficam ligados a ele).",
"rpg_signin_title": "Conecte a conta à PlayStation Network (offline)",
"rpg_signin_body": "O PS5 só deixa uma conta conectada usar a Reprodução Remota. Se a opção de Reprodução Remota do próprio console estiver acinzentada, execute o login offline abaixo (nada é enviado à Sony) e depois reinicie o PS5. Dá para desfazer.",
"rpg_signin_fix": "Ir para o login",
"rpg_service_title": "Ative a Reprodução Remota",
"rpg_service_body": "Ajustes › Sistema › Reprodução Remota › Ativar Reprodução Remota. O app pode ativar isso para você e, no firmware 10.00 e posterior, também permitir para este usuário.",
"rpg_rest_title": "Permita ligar o PS5 a partir do modo de repouso",
"rpg_rest_body": "Ajustes › Sistema › Economia de energia › Recursos disponíveis no modo de repouso: ative «Permanecer conectado à Internet» e «Ativar ligar o PS5 pela rede». Sem eles, um console em modo de repouso não pode ser ligado e a rede dele adormece após alguns segundos. Só o console mostra essas opções.",
"rpg_pair_title": "Pareie este app com o console",
"rpg_pair_body": "Conexão › Ligar e entrar › Configurar. Um clique registra este app no PS5 (como parear o app PS Remote Play) e guarda as chaves neste computador. Transmissão, ligar e login usam essas chaves; faça de novo depois de redefinir o console ou trocar de usuário.",
"rpg_play_title": "Jogar",
"rpg_play_body": "Abra a Reprodução Remota e toque em Iniciar: o app liga o console se estiver em repouso, faz login e transmite. Jogue com um controle conectado a este computador, pelo teclado ou por toque. Para usar o app PS Remote Play da Sony ou o chiaki-ng, solicite um PIN abaixo e digite-o lá.",
"rpg_play_fix": "Abrir Reprodução Remota",
"rpg_title": "Configurar a Reprodução Remota",
"rpg_progress": "{done} de {n} etapas verificadas concluídas",
"rpg_on_console": "verifique no console",
"rpg_trouble": "Se ainda não funcionar",
"rpg_t_start_q": "Iniciar está desativado na tela Jogar.",
"rpg_t_start_a": "Este app ainda não está pareado com esse console: faça a etapa 6 (Conexão › Ligar e entrar › Configurar).",
"rpg_t_pair_q": "Ao configurar o pareamento, aparece que não há usuário conectado com uma conta ativada.",
"rpg_t_pair_a": "Etapas 1 e 2: entre com um usuário no PS5 e dê a ele um ID de conta; depois tente de novo.",
"rpg_t_grey_q": "A opção de Reprodução Remota do próprio PS5 está acinzentada.",
"rpg_t_grey_a": "A conta não está conectada à PlayStation Network. Execute o login offline (etapa 3) e reinicie o PS5.",
"rpg_t_wake_q": "O console não liga, ou liga mas fica na tela de seleção de usuário.",
"rpg_t_wake_a": "Verifique a etapa 5 no console. Um usuário com senha de acesso impede o login automático. Se o console foi redefinido ou o usuário mudou, configure o pareamento de novo (etapa 6).",
"rpg_t_black_q": "A imagem fica preta, trava ou o som chia.",
"rpg_t_black_a": "Use conexão com fio ou Wi-Fi de 5 GHz no PS5 e neste computador, e experimente 720p ou 30 fps nas configurações da Reprodução Remota. O firewall deste computador precisa permitir o app na rede local (a Reprodução Remota usa as portas TCP e UDP 9295–9304). No navegador, use um Chrome, Edge ou Safari atual: a imagem precisa de WebCodecs.",
"rpg_t_busy_q": "Diz que o PS5 ainda está encerrando a última sessão, ou que outro console está transmitindo.",
"rpg_t_busy_a": "Só um console transmite por vez, e o PS5 precisa de até 30 segundos depois que uma sessão termina. Pare a outra transmissão, espere um pouco e toque em Iniciar de novo.",
"rpg_t_restrict_q": "Depois do login offline, os jogos pedem para desativar as restrições do console.",
"rpg_t_restrict_a": "Use Desfazer login nesta página e reinicie, ou retire a restrição em Ajustes › Família e controle dos pais › Restrições do console PS5 (senha 0000, a menos que você tenha mudado).",
