"workshop_description_v2": "Mude o formato de um jogo antes de ele ir para o PS5: crie um pacote (.pkg), uma imagem de jogo (.exfat, .ffpkg ou o menor .ffpfsc) ou uma pasta simples, ou veja dentro de uma imagem ou pacote e altere seus arquivos. O trabalho roda neste computador. Para enviar um jogo como está, use {send}.",
"cq_title_v2": "⑤ Fila",
"cq_about": "Criados um após o outro neste computador, cada um como ②, ③ e ④ estavam definidos quando foi adicionado. Adicione mais em ①, mesmo com a fila rodando; mude um jogo em espera pelo botão de opções dele.",
